<script setup>
import {ref,computed,onMounted,onUnmounted,nextTick,watch} from 'vue';
import {Link,usePage,router} from '@inertiajs/vue3';
import {primaryLinks,navigationSection,secondaryLinks,activeLink} from '../navigation.mjs';
import StudySheet from './StudySheet.vue';import Footer from './Footer.vue';import WhatsNew from './WhatsNew.vue';import Errors from './Errors.vue';import Avatar from './Avatar.vue';import BadgeCrew from './BadgeCrew.vue';import {art} from '../art';
const page=usePage(),tierDialog=ref(null),whatsNew=ref(null),header=ref(null),menu=ref(''),accountButton=ref(null),journeyTab=ref('journey');let observer;
const moreSheet=ref(null),studyPage=computed(()=>['Attempt','FlashcardDeck','MemoryExit'].includes(page.component));
const mainLinks=primaryLinks;
const section=computed(()=>navigationSection(page.url)),contextLinks=computed(()=>secondaryLinks(page.url));
const active=url=>section.value===url;
const rank=computed(()=>page.props.achievement),community=computed(()=>page.props.community);
function closeMenu(e){if(e.type==='keydown'&&e.key!=='Escape')return;if(e.type==='pointerdown'&&e.target.closest('[data-menu]'))return;const was=menu.value;menu.value='';if(e.type==='keydown'&&was==='account')accountButton.value?.focus()}
function toggle(which){menu.value=menu.value===which?'':which}
function journey(tab='journey'){journeyTab.value=tab;menu.value='';tierDialog.value.showModal()}
function menuKeys(e){const items=[...e.currentTarget.querySelectorAll('a,button')];const i=items.indexOf(document.activeElement);if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();items[e.key==='Home'?0:e.key==='End'?items.length-1:(i+(e.key==='ArrowDown'?1:-1)+items.length)%items.length]?.focus()}}
watch(()=>page.url,()=>menu.value='');
watch(journeyTab,()=>nextTick(()=>{const scroller=tierDialog.value?.querySelector('.journey-scroll');if(scroller)scroller.scrollTop=0}));
onMounted(()=>{observer=new ResizeObserver(()=>document.documentElement.style.setProperty('--header-height',header.value.offsetHeight+'px'));observer.observe(header.value);document.addEventListener('pointerdown',closeMenu);document.addEventListener('keydown',closeMenu)});
onUnmounted(()=>{observer?.disconnect();document.removeEventListener('pointerdown',closeMenu);document.removeEventListener('keydown',closeMenu)});
const practice=[['Maki Mentor','/practice?mode=tutor'],['Wasabi Rush','/practice?mode=exam'],['Roll Call','/library'],['Bento Builder','/exams']];
const social=[['Sushi Passport','/passport'],['Leaderboard','/leaderboard']];
</script>
<template><div class="app-shell compact-shell" :class="{'study-focused':studyPage,'counter-page':page.component==='Home'}"><a class="skip-link" href="#main">Skip to content</a><header ref="header" class="sticky compact-header"><div class="compact-topbar">
<Link v-if="studyPage" href="/" class="study-back">← Study</Link><Link v-else href="/" class="compact-brand" aria-label="Sushi study home"><img :src="art.logo" alt=""><strong>SUSHI</strong></Link>
<nav v-if="!studyPage" class="desktop-nav" aria-label="Main navigation"><Link v-for="[name,url] in mainLinks" :key="url" :href="url" :class="{active:active(url)}" :aria-current="active(url)?'page':undefined">{{name}}</Link><button @click="moreSheet.open()">More</button></nav>
<div class="account" data-menu><button ref="accountButton" class="profile-trigger" @click="toggle('account')" :aria-expanded="menu==='account'" aria-controls="account-menu" aria-label="Account menu"><Avatar :avatar="community?.profile.avatar" size="small"/><span class="account-label">Account</span></button>
<div v-if="menu==='account'" id="account-menu" class="dropdown account-dropdown" @keydown="menuKeys"><strong>{{community?.profile.display_name}}</strong><Link href="/profile">My profile</Link><button @click="journey()">Sushi journey</button><Link href="/updates">Study updates<span v-if="page.props.unreadUpdates"> · {{page.props.unreadUpdates}}</span></Link><button @click="menu='';whatsNew.open()">Changelog</button><Link href="/tour">{{page.props.release?.tour_name||'System tour'}}</Link><Link href="/settings">Settings</Link><Link href="/password">Change password</Link><Link href="/import">Import progress</Link><Link v-if="page.props.user.role==='admin'" href="/admin">Head Chef</Link><button @click="router.post('/logout')">Sign out</button></div></div></div></header>
<nav v-if="!studyPage&&contextLinks.length" class="section-nav" aria-label="Section navigation"><Link v-for="[name,url] in contextLinks" :key="url" :href="url" :class="{active:activeLink(page.url,url)}" :aria-current="activeLink(page.url,url)?'page':undefined">{{name}}</Link></nav>
<main id="main" tabindex="-1" class="main"><Link v-if="page.props.unreadUpdates&&!studyPage" href="/updates" class="update-link">{{page.props.unreadUpdates}} study updates →</Link><p v-if="page.props.flash" class="notice" role="status">{{page.props.flash}}</p><Errors :errors="page.props.errors"/><slot/></main><Footer v-if="!studyPage"/><WhatsNew ref="whatsNew" :defer="studyPage"/>
<nav v-if="!studyPage" class="mobile-tabs" aria-label="Mobile navigation"><Link v-for="([name,url],i) in mainLinks" :key="url" :href="url" :class="{active:active(url)}" :aria-current="active(url)?'page':undefined" :aria-label="name">{{name}}</Link><button @click="moreSheet.open()">More</button><button data-menu @click="toggle('account')" :aria-expanded="menu==='account'" aria-controls="account-menu">Account</button></nav>
<StudySheet ref="moreSheet" title="Study tools"><p class="section-description">Choose a study mode or visit your study community.</p><div class="more-links"><Link v-for="[name,url] in [...practice,...social,['Today’s Bento','/practice?mode=bento']]" :key="url" :href="url" @click="moreSheet.close()">{{name}} <span aria-hidden="true">→</span></Link></div></StudySheet>
<dialog ref="tierDialog" class="journey-dialog" @click="e=>{if(e.target===tierDialog)tierDialog.close()}"><div class="journey-header"><div><p class="eyebrow">Your collection, your pace</p><h2>Your sushi journey</h2></div><button @click="tierDialog.close()" aria-label="Close your sushi journey">✕</button><div class="journey-tabs"><button :class="{selected:journeyTab==='journey'}" @click="journeyTab='journey'">Journey</button><button :class="{selected:journeyTab==='crew'}" @click="journeyTab='crew'">Achievement Crew · {{community?.badge_count}} / {{community?.badge_total}}</button></div></div>
<div class="journey-scroll" tabindex="0"><template v-if="journeyTab==='journey'"><div class="journey-profile"><Avatar :avatar="community?.profile.avatar" size="large"/><div><h3>{{rank?.name}}</h3><p>{{rank?.count}} unique questions completed. {{rank?.remaining}} to {{rank?.next}}.</p><div class="meter"><i :style="{width:rank?.percent+'%'}"></i></div></div></div><p>Every 200 unique completed questions earns another tier. Checked answers and answered Memory Maki cards share the count. Repeats are practice; new questions keep your journey growing.</p>
<section class="journey-frames"><h3>Your portrait frames</h3><p>Bronze, Silver, Gold, and Sakura decorate your portrait. Your sushi tier keeps its own name.</p><div class="frame-choices"><div v-for="f in rank?.frames" :key="f.id" :class="{selected:community?.profile.avatar.frame===f.id}"><Avatar :avatar="{...community?.profile.avatar,frame:f.id}"/><strong>{{f.name}}</strong><small>{{!f.unlocked?'At '+f.at+' questions':community?.profile.avatar.frame===f.id?'Equipped':'Unlocked'}}</small></div></div><Link href="/profile#frames" class="button spaced" @click="tierDialog.close()">Choose a portrait frame</Link></section>
<h3 class="spaced">Your sushi tiers</h3><p>Five new characters join the journey from 5,200 to 6,000 questions. Unlock their portraits in your Character Closet. Tier thresholds stay fixed as the bank grows.</p><ol class="rank-stages"><li v-for="t in rank?.tiers" :key="t.at" :class="{earned:rank.count>=t.at}"><Avatar :avatar="t.image?{image:t.image,name:t.name,frame:community?.profile.avatar.frame}:community?.profile.avatar" /><div><strong>{{t.name}}</strong><small>{{t.at.toLocaleString()}} questions</small></div><span v-if="rank.count>=t.at">✓</span></li></ol></template>
<BadgeCrew v-else :badges="community?.badges||[]" compact/></div></dialog></div></template>
